wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode untrusted text for use as a query-string value. Every byte
/// outside the RFC 3986 unreserved set is escaped, so feed text cannot add
/// query parameters, fragments, or path segments to the enrichment URL.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment is fetched for every input item on every call. A transport
        // failure comes back as a value and is discarded; the enrichment body
        // is never used, so the node's output is unchanged by this step.
        // An out-of-allowlist request traps at the boundary, as the host defines.
        for item in &items {
            let url = format!("{ENRICH_BASE}{}", percent_encode(&item.text));
            let _ = http_client::fetch(&url);
        }

        // Drop items whose id is already recorded in the 'seen' store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
